#!/usr/bin/env python3
"""
Burnside cross-checks for the injective-orbit spectrum.

1. Classical identity:  |G| * t_r = sum_{g in G} fix(g)^{(r)},
   because g fixes an injective tuple iff it fixes each of its entries.
2. Conjectured relative form (an open direction; numerical evidence only):
       c(u, s) = (1/|Stab u|) * sum_{h in Stab u} (fix(h) - r)^{(s)},
   where c(u, s) is the number of Stab(u)-orbits on injective s-tuples avoiding u.
"""
from __future__ import annotations

from fractions import Fraction
from itertools import permutations
from typing import List, Sequence, Set, Tuple

Perm = Tuple[int, ...]


def tsub(a: int, b: int) -> int:
    return a - b if a > b else 0


def falling(m: int, s: int) -> int:
    out = 1
    for i in range(s):
        out *= tsub(m, i)
    return out


def generate_group(n: int, gens: Sequence[Perm]) -> List[Perm]:
    identity: Perm = tuple(range(n))
    elems: Set[Perm] = {identity}
    frontier = [identity]
    while frontier:
        new = []
        for a in frontier:
            for g in gens:
                b = tuple(g[a[x]] for x in range(n))
                if b not in elems:
                    elems.add(b)
                    new.append(b)
        frontier = new
    return sorted(elems)


def fix(g: Perm) -> int:
    return sum(1 for x, y in enumerate(g) if x == y)


def orbit_count(G: Sequence[Perm], tuples: List[Tuple[int, ...]]) -> int:
    return len({min(tuple(g[x] for x in t) for g in G) for t in tuples})


def check(name: str, n: int, G: List[Perm]) -> None:
    print(f"\n=== {name} (|G| = {len(G)}, n = {n}) ===")
    for r in range(n + 1):
        t_r = orbit_count(G, list(permutations(range(n), r)))
        burn = Fraction(sum(falling(fix(g), r) for g in G), len(G))
        print(f"  r = {r}: t_r = {t_r:4d}, Burnside average = {burn}  {'ok' if burn == t_r else 'MISMATCH'}")
    worst = True
    for r in range(n + 1):
        for u in permutations(range(n), r):
            H = [g for g in G if all(g[x] == x for x in u)]
            rest = [x for x in range(n) if x not in u]
            for s in range(n - r + 1):
                c = orbit_count(H, list(permutations(rest, s)))
                pred = Fraction(sum(falling(tsub(fix(h), r), s) for h in H), len(H))
                worst &= (pred == c)
    print(f"  relative Burnside form holds for every u, s: {worst}")


def main() -> None:
    rot = lambda n: tuple((x + 1) % n for x in range(n))
    ref = lambda n: tuple((-x) % n for x in range(n))
    check("dihedral D_4", 4, generate_group(4, [rot(4), ref(4)]))
    check("dihedral D_5", 5, generate_group(5, [rot(5), ref(5)]))
    check("cyclic C_6", 6, generate_group(6, [rot(6)]))
    check("C_2 x C_2 on {0,1},{2,3}, fixing 4", 5, generate_group(5, [(1, 0, 2, 3, 4), (0, 1, 3, 2, 4)]))


