from itertools import permutations
from typing import List, Sequence, Tuple

Perm = Tuple[int, ...]
Tup = Tuple[int, ...]


def canonical_form(G: Sequence[Perm], u: Tup) -> Tup:
    """Lexicographically least element of the orbit G.u (an exact orbit invariant)."""
    return min(tuple(g[x] for x in u) for g in G)


def injective_orbit_spectrum(G: Sequence[Perm], n: int) -> List[int]:
    """Return (t_0, ..., t_n): the number of G-orbits on injective r-tuples of {0..n-1}."""
    spectrum: List[int] = []
    for r in range(n + 1):
        forms = {canonical_form(G, u) for u in permutations(range(n), r)}
        spectrum.append(len(forms))
    return spectrum


def falling(m: int, s: int) -> int:
    out = 1
    for i in range(s):
        out *= max(m - i, 0)
    return out


def spectrum_by_burnside(G: Sequence[Perm], n: int) -> List[int]:
    """Same spectrum via |G| t_r = sum_g fix(g)^{(r)} (G must be finite and listed in full)."""
    fixes = [sum(1 for x in range(n) if g[x] == x) for g in G]
    return [sum(falling(f, r) for f in fixes) // len(G) for r in range(n + 1)]


