from typing import Dict, List, Tuple


def tsub(a: int, b: int) -> int:
    return a - b if a > b else 0


def falling(m: int, s: int) -> int:
    out = 1
    for i in range(s):
        out *= tsub(m, i)
    return out


def hierarchy_certificate(t: List[int]) -> Dict[str, List[Tuple[int, int]]]:
    """Given a candidate spectrum t = (t_0, ..., t_n), list every pair (r, s), r + s <= n,
    at which each inequality fails.  Failures of 'lower', 'upper' or 'repaired' prove that t is
    NOT the injective-orbit spectrum of any group action; failures of 'coarse' are expected."""
    n = len(t) - 1
    report: Dict[str, List[Tuple[int, int]]] = {"lower": [], "upper": [], "coarse": [], "repaired": []}
    for r in range(n + 1):
        for s in range(n + 1 - r):
            if t[r] * falling(tsub(t[1], r), s) > t[r + s]:
                report["lower"].append((r, s))
            if t[r + s] > t[r] * falling(n - r, s):
                report["upper"].append((r, s))
            if t[r] * tsub(t[s], r) > t[r + s]:
                report["coarse"].append((r, s))
            corr = falling(n, s) - falling(n - r, s)
            if t[r] * tsub(t[s], corr) > t[r + s]:
                report["repaired"].append((r, s))
    return report


if __name__ == "__main__":
    print(hierarchy_certificate([1, 3, 6, 6]))       # trivial group on 3 points: coarse fails at (1, 2)
    print(hierarchy_certificate([1, 1, 2, 3, 3]))    # dihedral D_4: no failures
    print(hierarchy_certificate([1, 2, 1, 1]))       # impossible spectrum: lower bound fails at (0, 2) and (1, 1)
